CREATE SET TABLE MDP01_META.META_INDEX_COLUMN ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      index_column_id INTEGER NOT NULL,      index_id INTEGER NOT NULL,      column_id INTEGER NOT NULL,      column_position INTEGER NOT NULL,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( index_column_id )UNIQUE INDEX ( index_id ,column_position );